p="/app/frontend/src/lib/i18n.js"; s=open(p).read()
s=s.replace('  { code: "ar", name: "العربية"','  { code: "bn", name: "বাংলা", flag: "🇧🇩", dir: "ltr" },\n  { code: "ar", name: "العربية"',1)
missing=[]
def sub(m):
    k=m.group(1)
    if k not in BN: missing.append(k); return m.group(0)
    return m.group(0)+', bn: "'+BN[k]+'"'
s=re.sub(r'^  ([a-z_0-9]+): \{ .*?hi: "[^"]*"(?= \})', sub, s, flags=re.M)
